// 1. Core Sequence Points (SP)
// SP guarantee all prior side effects are complete.
;                 // End of full expression statement
,                 // Comma operator (not separator)
&&, ||, ?:        // Logical and Conditional operators
function(arg1, arg2); // After arg evaluation/before call
return;           // Before control returns

// 2. Undefined Behavior (UB) - Multiple Modification
// Modifying the same object twice between SPs is UB.
int i = 5;
i = i++ + ++i;    // UB: i modified 3 times between ';'

int f(int);
i = f(i++) + i;   // UB: i modified and read post-modification
                  // without an intervening SP

// 3. Guaranteed Evaluation Order (Implied SP)
int a = 10;
(a > 5) && (a++); // If (a>5) is true, 'a++' is evaluated.
                  // SP occurs after (a > 5) evaluation.

int b = (a=1, a+1); // Comma operator sequences:
                    // 1. (a=1) completes (SP).
                    // 2. (a+1) evaluates (b=2).
